scwin.trigger1_onclick = function(e) {
    var options = {};
    options.fileName = "useDataFormat.xlsx"
    options.type = "1";
    options.startRowIndex = 0;
    options.startColumnIndex = 0;
    options.useDataFormat = "true";
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var options = {};
    options.fileName = "useDataFormat.xlsx"
    //options.type = "1";
    //options.startRowIndex = 0;
    //options.startColumnIndex = 0;
    //options.useDataFormat="false";
    options.autoSizeColumn = true;
    options.httpReadOnly = true;
    scwin.gridToExcelIncludeHidden(gridView1, options);
};
scwin.gridToExcelIncludeHidden = function(gridObj, opt) {
    // hidden 판별 후 전체컬럼 visible
    var cnt = gridObj.getColCnt();
    var hide = [];
    for (var i = 0; i < cnt; i++) {
        hide.push({
            "idx": i,
            "isHidden": gridObj.getColumnVisible(i)
        });
        gridObj.setColumnVisible(i, true);
    }
    // 엑셀 다운로드 
    gridObj.advancedExcelDownload(opt);
    // 기존 hidden 컬럼 다시 hidden 처리.
    for (var i = 0; i < cnt; i++) {
        if (!hide[i].isHidden) gridObj.setColumnVisible(i, hide[i].isHidden);
    }
};
scwin.trigger3_onclick = function() {
    var options = {
        headerExist: "1",
        sheetName: "sheet2"
    };
    gridView1.advancedExcelUpload(options);
};
scwin.displayFormatter = function(value) {
    value = Math.ceil(value);
    console.log("before: ", value);
    value = value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    console.log("after: ", value);
    return value;
};
